-- BloomCraft's real sales before the website went live (in-person handovers, paid by Google Pay).
-- Run once after seed.sql (Supabase → SQL Editor). Re-running is safe: existing orders are kept.
-- These customers gave no phone number, so these orders can be seen in the Maker Studio but not tracked.

-- Run this before the first website order: those would use the same numbers (BC-2026-00001 ...).
do $$
begin
  if exists (select 1 from public.orders where coalesce(payment ->> 'provider', '') <> 'Google Pay') then
    raise exception 'Website orders already exist, so past orders would clash with their numbers. Ask for help before importing.';
  end if;
end $$;

on conflict (id) do nothing;

-- New website orders continue the numbering after these (BC-2026-00019, ...).
select setval(
  'public.order_number_seq',
  greatest(
    (select coalesce(max(substring(id from '[0-9]+$')::integer), 0) from public.orders where id ~ '^BC-[0-9]{4}-[0-9]+$'),
    (select last_value from public.order_number_seq)
  )
);
